"""Test kit for dashboard/auth (phase 6b P1/P2; used by test_mds.py and test_passkeys.py), all
offline and synthetic:

  Pki            a test CA hierarchy: roots, intermediates, cross-certificates, TLS leaves,
                 packed-attestation certificates (cryptography's builders)
  make_blob()    an MDS3 blob (compact JWS, x5c header) signed by a Pki leaf; payload() / entry()
                 build the payload in MDS JSON form
  SoftAuthenticator  registrations (packed with x5c, self attestation, none) and assertion
                 authenticator data with chosen flags and counter
  VECTORS        recorded real-device attestations from python-fido2's test suite (TPM / Windows
                 Hello, packed, Apple, Android SafetyNet), under fido2's BSD-2-Clause licence (below)

Needs Python 3.12 with fido2 and cryptography (the .venv); imported only when they are there.
"""
from __future__ import annotations

import base64
import hashlib
import json
import os
from datetime import date, datetime, timedelta, timezone
from typing import Any, Optional, Sequence

from cryptography import x509
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec, padding, rsa
from cryptography.hazmat.primitives.asymmetric.utils import decode_dss_signature
from cryptography.x509.oid import ExtendedKeyUsageOID, NameOID
from fido2.cose import ES256
from fido2.webauthn import AttestationObject, AttestedCredentialData, AuthenticatorData

NOW = datetime(2026, 10, 22, 12, 0, tzinfo=timezone.utc)
HOST = "mds.fidoalliance.org"
RP_ID = "afc.example.test"
OID_AAGUID = x509.ObjectIdentifier("1.3.6.1.4.1.45724.1.1.4")
Key = Any   # ec / rsa private key


def b64url(data: bytes) -> bytes:
    return base64.urlsafe_b64encode(data).rstrip(b"=")


# --- PKI -----------------------------------------------------------------------------------------

def ec_key() -> ec.EllipticCurvePrivateKey:
    return ec.generate_private_key(ec.SECP256R1())


def rsa_key() -> rsa.RSAPrivateKey:
    return rsa.generate_private_key(public_exponent=65537, key_size=2048)


def name(cn: str, *, o: str = "AFClaude Test", c: str = "DE", ou: Optional[str] = None) -> x509.Name:
    attrs = [x509.NameAttribute(NameOID.COUNTRY_NAME, c), x509.NameAttribute(NameOID.ORGANIZATION_NAME, o)]
    if ou:
        attrs.append(x509.NameAttribute(NameOID.ORGANIZATIONAL_UNIT_NAME, ou))
    attrs.append(x509.NameAttribute(NameOID.COMMON_NAME, cn))
    return x509.Name(attrs)


def build(subject: x509.Name, key: Key, issuer: Optional[x509.Certificate], issuer_key: Key, *, ca: bool,
          start: datetime = NOW - timedelta(days=30), end: datetime = NOW + timedelta(days=300),
          dns: Optional[str] = None, server_auth: bool = False, path_len: Optional[int] = None,
          extensions: Sequence[x509.ExtensionType] = ()) -> x509.Certificate:
    pub = key.public_key()
    b = (x509.CertificateBuilder().subject_name(subject).issuer_name(issuer.subject if issuer else subject)
         .public_key(pub).serial_number(x509.random_serial_number()).not_valid_before(start).not_valid_after(end)
         .add_extension(x509.BasicConstraints(ca=ca, path_length=path_len if ca else None), critical=True)
         .add_extension(x509.SubjectKeyIdentifier.from_public_key(pub), critical=False)
         .add_extension(x509.AuthorityKeyIdentifier.from_issuer_public_key(
             (issuer_key if issuer else key).public_key()), critical=False))
    if ca:
        b = b.add_extension(x509.KeyUsage(digital_signature=True, content_commitment=False, key_encipherment=False,
                                          data_encipherment=False, key_agreement=False, key_cert_sign=True,
                                          crl_sign=True, encipher_only=False, decipher_only=False), critical=True)
    else:
        b = b.add_extension(x509.KeyUsage(digital_signature=True, content_commitment=False, key_encipherment=False,
                                          data_encipherment=False, key_agreement=False, key_cert_sign=False,
                                          crl_sign=False, encipher_only=False, decipher_only=False), critical=True)
    if dns:
        b = b.add_extension(x509.SubjectAlternativeName([x509.DNSName(dns)]), critical=False)
    if server_auth:
        b = b.add_extension(x509.ExtendedKeyUsage([ExtendedKeyUsageOID.SERVER_AUTH]), critical=False)
    for ext in extensions:
        b = b.add_extension(ext, critical=False)
    return b.sign(issuer_key if issuer else key, hashes.SHA256())


def der(cert: x509.Certificate) -> bytes:
    return cert.public_bytes(serialization.Encoding.DER)


class Pki:
    """Old root -> (cross) -> new root -> intermediate -> leaf, like FIDO's R3 / R46 move."""

    def __init__(self, *, leaf_rsa: bool = False, host: str = HOST, int_end: Optional[datetime] = None) -> None:
        self.old_key, self.root_key, self.int_key = ec_key(), ec_key(), ec_key()
        self.leaf_key: Key = rsa_key() if leaf_rsa else ec_key()
        self.old_root = build(name("Test Old Root"), self.old_key, None, self.old_key, ca=True,
                              start=NOW - timedelta(days=3000), end=NOW + timedelta(days=3000))
        self.root = build(name("Test Root R46"), self.root_key, None, self.root_key, ca=True,
                          start=NOW - timedelta(days=1000), end=NOW + timedelta(days=5000))
        self.cross = build(name("Test Root R46"), self.root_key, self.old_root, self.old_key, ca=True,
                           start=NOW - timedelta(days=1000), end=NOW + timedelta(days=900))
        self.intermediate = build(name("Test MDS CA"), self.int_key, self.root, self.root_key, ca=True, path_len=0,
                                  end=int_end or NOW + timedelta(days=900), server_auth=True)
        self.leaf = build(name(host), self.leaf_key, self.intermediate, self.int_key, ca=False, dns=host,
                          server_auth=True)

    @property
    def x5c(self) -> list[x509.Certificate]:
        return [self.leaf, self.intermediate]


# --- MDS payload and blob ------------------------------------------------------------------------

def entry(*, aaguid: Optional[str] = None, key_ids: Sequence[bytes] = (), statuses: Sequence[str] = ("FIDO_CERTIFIED_L1",),
          key_protection: Sequence[str] = ("hardware", "secure_element"), roots: Sequence[bytes] = (),
          description: str = "Test Security Key", multi_device: Optional[str] = None,
          drop: Sequence[str] = (), statement: bool = True) -> dict[str, Any]:
    """One MDS entry; `statuses` oldest first, a day apart; `drop` removes statement keys."""
    start = date(2025, 1, 1)
    e: dict[str, Any] = {
        "statusReports": [{"status": s, "effectiveDate": (start + timedelta(days=i)).isoformat()}
                          for i, s in enumerate(statuses)],
        "timeOfLastStatusChange": start.isoformat()}
    if aaguid:
        e["aaguid"] = aaguid
    if key_ids:
        e["attestationCertificateKeyIdentifiers"] = [k.hex() for k in key_ids]
    if statement:
        st: dict[str, Any] = {
            "legalHeader": "test", "description": description, "authenticatorVersion": 1, "schema": 3,
            "upv": [{"major": 1, "minor": 1}], "attestationTypes": ["basic_full"],
            "userVerificationDetails": [[{"userVerificationMethod": "presence_internal"}]],
            "keyProtection": list(key_protection), "matcherProtection": ["on_chip"],
            "attachmentHint": ["external"], "tcDisplay": [],
            "attestationRootCertificates": [base64.b64encode(r).decode() for r in roots],
            "protocolFamily": "fido2"}
        if aaguid:
            st["aaguid"] = aaguid
        if key_ids:
            st["attestationCertificateKeyIdentifiers"] = [k.hex() for k in key_ids]
        if multi_device:
            st["multiDeviceCredentialSupport"] = multi_device
        for k in drop:
            st.pop(k, None)
        e["metadataStatement"] = st
    return e


def payload(entries: Sequence[dict[str, Any]], *, no: int = 291, next_update: date = date(2026, 11, 1)) -> dict[str, Any]:
    return {"legalHeader": "test blob", "no": no, "nextUpdate": next_update.isoformat(), "entries": list(entries)}


def make_blob(body: dict[str, Any], key: Key, x5c: Sequence[x509.Certificate], *, alg: str = "ES256",
              header: Optional[dict[str, Any]] = None, raw_payload: Optional[bytes] = None) -> bytes:
    h: dict[str, Any] = {"alg": alg, "typ": "JWT", "x5c": [base64.b64encode(der(c)).decode() for c in x5c]}
    h.update(header or {})
    signing = b64url(json.dumps(h).encode()) + b"." + b64url(raw_payload if raw_payload is not None
                                                              else json.dumps(body).encode())
    if alg == "ES256":
        r, s = decode_dss_signature(key.sign(signing, ec.ECDSA(hashes.SHA256())))
        sig = r.to_bytes(32, "big") + s.to_bytes(32, "big")
    elif alg == "RS256":
        sig = key.sign(signing, padding.PKCS1v15(), hashes.SHA256())
    elif alg == "HS256":
        import hmac
        sig = hmac.new(b"secret", signing, hashlib.sha256).digest()
    else:
        sig = b""
    return signing + b"." + b64url(sig)


# --- soft authenticator --------------------------------------------------------------------------

class AttestationCa:
    """A maker's attestation root and one batch certificate under it (packed requirements)."""

    def __init__(self, aaguid: bytes, *, with_aaguid_ext: bool = True) -> None:
        self.root_key, self.key = ec_key(), ec_key()
        self.root = build(name("Test Attestation Root", o="Test Maker"), self.root_key, None, self.root_key, ca=True)
        ext = [x509.UnrecognizedExtension(OID_AAGUID, b"\x04\x10" + aaguid)] if with_aaguid_ext else []
        self.cert = build(name("Test Batch", o="Test Maker", ou="Authenticator Attestation"), self.key,
                          self.root, self.root_key, ca=False, extensions=ext)

    @property
    def key_id(self) -> bytes:
        return x509.SubjectKeyIdentifier.from_public_key(self.cert.public_key()).digest


F = AuthenticatorData.FLAG


def flags(*, up: bool = True, uv: bool = True, be: bool = False, bs: bool = False, at: bool = False) -> AuthenticatorData.FLAG:
    f = F(0)
    for on, bit in ((up, F.UP), (uv, F.UV), (be, F.BE), (bs, F.BS), (at, F.AT)):
        if on:
            f |= bit
    return f


class SoftAuthenticator:
    def __init__(self, aaguid: bytes = b"\x11" * 16, ca: Optional[AttestationCa] = None) -> None:
        self.aaguid, self.ca = aaguid, ca
        self.cred_key = ec_key()
        self.cred_id = os.urandom(32)
        self.rp_hash = hashlib.sha256(RP_ID.encode()).digest()

    def register(self, *, fmt: str = "packed", self_attest: bool = False, uv: bool = True, be: bool = False,
                 bs: bool = False, counter: int = 0, tamper: bool = False) -> tuple[AttestationObject, bytes]:
        cdh = os.urandom(32)
        cred = AttestedCredentialData.create(self.aaguid, self.cred_id,
                                             ES256.from_cryptography_key(self.cred_key.public_key()))
        ad = AuthenticatorData.create(self.rp_hash, flags(uv=uv, be=be, bs=bs, at=True), counter, cred)
        if fmt == "none":
            return AttestationObject.create("none", ad, {}), cdh
        if fmt != "packed":
            return AttestationObject.create(fmt, ad, {"alg": -7, "sig": b"x"}), cdh
        signer = self.cred_key if self_attest or self.ca is None else self.ca.key
        sig = signer.sign(bytes(ad) + cdh, ec.ECDSA(hashes.SHA256()))
        if tamper:
            sig = sig[:-2] + bytes([sig[-2] ^ 1]) + sig[-1:]
        stmt: dict[str, Any] = {"alg": -7, "sig": sig}
        if not (self_attest or self.ca is None):
            stmt["x5c"] = [der(self.ca.cert)]
        return AttestationObject.create("packed", ad, stmt), cdh

    def assertion(self, *, counter: int, uv: bool = True, be: bool = False, bs: bool = False) -> AuthenticatorData:
        return AuthenticatorData.create(self.rp_hash, flags(uv=uv, be=be, bs=bs), counter)


def uuid_str(aaguid: bytes) -> str:
    h = aaguid.hex()
    return f"{h[:8]}-{h[8:12]}-{h[12:16]}-{h[16:20]}-{h[20:]}"


